type agreementCommentHeadingDeclaration struct {
	ID, Raw string
	Span    graph.Span
	Owner   int
}

type agreementCommentHeadingSource struct {
	Original, Projected agreementNativeHeadingSource
	Masked              string
	Declarations        []agreementCommentHeadingDeclaration
	Kept                agreementMixedNamespaceReading
	Outside             []agreementNativeCheckField
	Selected            map[string]bool
	Valid               bool
}

// A comment may swallow a code declaration written after its opener. Keep both
// complete readings rather than treating that declaration as a live owner.
// A private equal-width mask must remove exactly the declared hidden headings;
// every outside heading and check field keeps its source position and role.
func agreementCommentHeadingReading(body string) agreementCommentHeadingSource {
	r := agreementCommentHeadingSource{Original: agreementNativeHeadingReading(body), Selected: make(map[string]bool), Valid: true}
	before := &r.Original
	comments := before.Check.Comments
	if !before.Plain.Eligible || !before.Page.Eligible || !cmp.Equal(before.Plain, before.Page) || len(comments) == 0 || !cmp.Equal(comments, before.Native.Comments) || len(before.Allocated) != len(before.Page.Headings) {
		r.Valid = false
		return r
	}
	masked := []byte(body)
	for _, span := range comments {
		for at := span.Start; at < span.Stop; at++ {
			if masked[at] != '\n' && masked[at] != '\r' {
				masked[at] = ' '
			}
		}
	}
	r.Masked = string(masked)
	r.Projected = agreementNativeHeadingReading(r.Masked)
	r.Kept.Eligible = before.Page.Eligible
	for i, span := range before.Page.Headings {
		owner, valid := agreementCommentHeadingOwner(span, comments)
		r.Valid = r.Valid && valid
		id := before.Allocated[i]
		r.Declarations = append(r.Declarations, agreementCommentHeadingDeclaration{ID: id, Raw: body[span.Start:span.Stop], Span: span, Owner: owner})
		if owner >= 0 {
			if !before.Names[id] {
				r.Selected[id] = true
			}
			continue
		}
		r.Kept.Headings = append(r.Kept.Headings, span)
		r.Kept.Bases = append(r.Kept.Bases, before.Page.Bases[i])
		r.Kept.Checks = append(r.Kept.Checks, before.Page.Checks[i])
	}
	for _, span := range before.Page.Code {
		owner, valid := agreementCommentHeadingOwner(span, comments)
		r.Valid = r.Valid && valid
		if owner < 0 {
			r.Kept.Code = append(r.Kept.Code, span)
		}
	}
	for _, field := range before.Page.Fields {
		owner, valid := agreementCommentHeadingOwner(field.Span, comments)
		r.Valid = r.Valid && valid
		if owner < 0 {
			r.Kept.Fields = append(r.Kept.Fields, field)
		}
	}
	for _, field := range before.Check.Fields {
		owner, valid := agreementCommentHeadingOwner(field.Span, comments)
		r.Valid = r.Valid && valid && field.Comment == (owner >= 0)
		if owner < 0 {
			r.Outside = append(r.Outside, field)
		}
	}
	after := &r.Projected
	if !after.Plain.Eligible || !after.Page.Eligible || !cmp.Equal(after.Plain, after.Page) || !cmp.Equal(r.Kept, after.Page) || !cmp.Equal(r.Outside, after.Check.Fields) || len(after.Native.Comments) != 0 || len(after.Check.Comments) != 0 || !cmp.Equal(before.Names, after.Names) || !cmp.Equal(before.Check.Targets, after.Check.Targets) || !cmp.Equal(before.Check.Targets, judge.LinkTargets(body)) || !cmp.Equal(after.Check.Targets, judge.LinkTargets(r.Masked)) {
		r.Valid = false
	}
	return r
}

func agreementCommentHeadingOwner(span graph.Span, comments []graph.Span) (int, bool) {
	if span.Start < 0 || span.Stop <= span.Start {
		return -1, false
	}
	owner := -1
	for i, comment := range comments {
		if span.Stop <= comment.Start || comment.Stop <= span.Start {
			continue
		}
		if owner >= 0 || span.Start < comment.Start || comment.Stop < span.Stop {
			return -1, false
		}
		owner = i
	}
	return owner, true
}

type agreementCommentHeadingPayload struct {
	Body     string
	Source   agreementCommentHeadingSource
	Headings []string
}

func agreementCommentHeadingBudget(t *testing.T, body string, actual *agreementHTML) agreementCommentHeadingPayload {
	t.Helper()
	r := agreementCommentHeadingReading(body)
	if !r.Valid || len(r.Selected) == 0 || !cmp.Equal(r.Original.Allocated, actual.Headings) {
		return agreementCommentHeadingPayload{}
	}
	_, witness := agreementIsolatedPage(t, agreementCase{Body: r.Masked})
	if !cmp.Equal(r.Projected.Allocated, witness.Headings) {
		return agreementCommentHeadingPayload{}
	}
	return agreementCommentHeadingPayload{Body: body, Source: r, Headings: slices.Clone(witness.Headings)}
}

func agreementCommentHeadingDifference(c agreementCase, f *agreementFailure, actual *agreementHTML, budget *agreementCommentHeadingPayload) (kind, authority, wrong string) {
	if c.Body != budget.Body || c.Title != "" || len(c.Companions) != 0 || f.Property != "P4" || f.Identity != "literal-heading-id" || f.Tuple != (agreementCitation{}) || f.Direction != "page-only" || f.Multiplicity != 1 || !f.PagePresent || f.JudgeAccepted || f.ExcerptFound || f.Cut != "" || !budget.Source.Valid || !budget.Source.Selected[f.Fragment] {
		return "", "", ""
	}
	if !cmp.Equal(budget.Source, agreementCommentHeadingReading(c.Body)) || !cmp.Equal(budget.Source.Original.Allocated, actual.Headings) || !cmp.Equal(budget.Source.Projected.Allocated, budget.Headings) {
		return "", "", ""
	}
	return "debt", "#1011 stage 5", "page"
}

