func agreementCommentHeadingDrift(t *testing.T, c agreementCase, f *agreementFailure, actual *agreementHTML, budget *agreementCommentHeadingPayload) {
	t.Helper()
	for _, other := range []agreementCase{{Body: c.Body + "unowned"}, {Body: c.Body, Title: "title"}, {Body: c.Body, Companions: capturedBodies{"A.md": "words"}}} {
		if kind, _, _ := agreementCommentHeadingDifference(other, f, actual, budget); kind != "" {
			t.Fatal("caught: comment heading borrowed source or vault context")
		}
	}
	for _, change := range []func(*agreementFailure){
		func(f *agreementFailure) { f.Property = "unowned" }, func(f *agreementFailure) { f.Identity = "unowned" }, func(f *agreementFailure) { f.Direction = "unowned" }, func(f *agreementFailure) { f.Tuple.Target = "unowned" }, func(f *agreementFailure) { f.Tuple.Section = "unowned" }, func(f *agreementFailure) { f.Tuple.SourceRole = "unowned" }, func(f *agreementFailure) { f.Tuple.State = "unowned" }, func(f *agreementFailure) { f.Fragment = "unowned" }, func(f *agreementFailure) { f.Multiplicity++ }, func(f *agreementFailure) { f.Multiplicity = 0 }, func(f *agreementFailure) { f.Multiplicity = -1 }, func(f *agreementFailure) { f.PagePresent = false }, func(f *agreementFailure) { f.JudgeAccepted = true }, func(f *agreementFailure) { f.ExcerptFound = true }, func(f *agreementFailure) { f.Cut = "unowned" },
	} {
		changed := *f
		change(&changed)
		if kind, _, _ := agreementCommentHeadingDifference(c, &changed, actual, budget); kind != "" {
			t.Fatalf("caught: comment heading borrowed signature %s", agreementSignature(&changed))
		}
	}
	drifts := [][]string{nil, actual.Headings[:len(actual.Headings)-1], append(slices.Clone(actual.Headings), "unowned")}
	changedNames := slices.Clone(actual.Headings)
	changedNames[0] += "-unowned"
	drifts = append(drifts, changedNames)
	if len(actual.Headings) > 1 {
		reordered := slices.Clone(actual.Headings)
		reordered[0], reordered[1] = reordered[1], reordered[0]
		drifts = append(drifts, reordered)
	}
	for _, headings := range drifts {
		changed := *actual
		changed.Headings = headings
		if kind, _, _ := agreementCommentHeadingDifference(c, f, &changed, budget); kind != "" {
			t.Fatal("caught: comment heading borrowed changed whole page namespace")
		}
		if agreementCommentHeadingBudget(t, c.Body, &changed).Body != "" {
			t.Fatal("caught: comment heading budget borrowed changed whole page namespace")
		}
	}

	projected := *budget
	projected.Headings = append(slices.Clone(budget.Headings), "unowned")
	if kind, _, _ := agreementCommentHeadingDifference(c, f, actual, &projected); kind != "" {
		t.Fatal("caught: comment heading borrowed changed projected namespace")
	}
}

