func TestAgreementCommentHeadingOwner(t *testing.T) {
	t.Parallel()
	for _, tc := range []struct {
		name     string
		span     graph.Span
		comments []graph.Span
		owner    int
		valid    bool
	}{
		{"left boundary", graph.Span{Start: 0, Stop: 2}, []graph.Span{{Start: 2, Stop: 7}}, -1, true},
		{"right boundary", graph.Span{Start: 7, Stop: 9}, []graph.Span{{Start: 2, Stop: 7}}, -1, true},
		{"contained", graph.Span{Start: 3, Stop: 5}, []graph.Span{{Start: 2, Stop: 7}}, 0, true},
		{"second owner", graph.Span{Start: 9, Stop: 11}, []graph.Span{{Start: 2, Stop: 7}, {Start: 8, Stop: 12}}, 1, true},
		{"partial left", graph.Span{Start: 1, Stop: 3}, []graph.Span{{Start: 2, Stop: 7}}, -1, false},
		{"partial right", graph.Span{Start: 5, Stop: 8}, []graph.Span{{Start: 2, Stop: 7}}, -1, false},
		{"covers owner", graph.Span{Start: 1, Stop: 8}, []graph.Span{{Start: 2, Stop: 7}}, -1, false},
		{"ambiguous owner", graph.Span{Start: 3, Stop: 5}, []graph.Span{{Start: 2, Stop: 7}, {Start: 2, Stop: 7}}, -1, false},
		{"zero span", graph.Span{Start: 3, Stop: 3}, nil, -1, false},
		{"reversed span", graph.Span{Start: 5, Stop: 3}, nil, -1, false},
		{"negative span", graph.Span{Start: -1, Stop: 3}, nil, -1, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			owner, valid := agreementCommentHeadingOwner(tc.span, tc.comments)
			if owner != tc.owner || valid != tc.valid {
				t.Fatalf("caught: comment heading unique physical owner=%d/%t want=%d/%t", owner, valid, tc.owner, tc.valid)
			}
		})
	}
}
